//! Reads geometry generated by the user's PE32 SpeedTreeRT DLL. No SPT approximation.
use crate::{pck, scene};
use std::{
    collections::HashMap,
    fs::{self, File},
    path::Path,
};
#[derive(Clone)]
pub struct Vert {
    pub pos: [f32; 3],
    pub normal: [f32; 3],
    pub uv: [f32; 2],
}
#[derive(Default)]
pub struct Part {
    pub vertices: Vec<Vert>,
    pub indices: Vec<u32>,
}
pub struct Leaf {
    pub center: [f32; 3],
    pub rho: f32,
    pub corners: [[f32; 3]; 4],
    pub uv: [[f32; 2]; 4],
    pub cluster: u32,
}
pub struct TreeLod {
    pub branch: Part,
    pub frond: Part,
    /// Native SpeedTree alpha-test references (0..255), present in PWTREE08.
    /// Older caches retain `None` so the renderer can preserve its legacy cutout.
    pub branch_alpha_ref: Option<f32>,
    pub frond_alpha_ref: Option<f32>,
    pub leaves: Vec<Leaf>,
    // Each cluster/corner has 64 runtime samples, stored in local camera space.
    pub rocking: Vec<[f32; 3]>,
    pub rocking_clusters: usize,
}
pub struct TreeMesh {
    pub lods: Vec<TreeLod>,
    pub bark: image::RgbaImage,
    pub composite: image::RgbaImage,
    /// Authored lower mip levels (1..N) retained for the opt-in P4.07 path.
    /// Empty when the source chain is unavailable; the default path ignores them.
    pub bark_mips: Vec<image::RgbaImage>,
    pub composite_mips: Vec<image::RgbaImage>,
}
pub struct Trees {
    pub types: Vec<Option<TreeMesh>>,
    pub placements: Vec<scene::Tree>,
}
struct Reader<'a> {
    d: &'a [u8],
    p: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8], String> {
        let e = self.p.checked_add(n).ok_or("tree offset overflow")?;
        let s = self.d.get(self.p..e).ok_or("truncated tree cache")?;
        self.p = e;
        Ok(s)
    }
    fn u(&mut self) -> Result<u32, String> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
    }
    fn f(&mut self) -> Result<f32, String> {
        let f = f32::from_bits(self.u()?);
        if !f.is_finite() {
            return Err("non-finite tree data".into());
        }
        Ok(f)
    }
    fn vec3(&mut self) -> Result<[f32; 3], String> {
        Ok([self.f()?, self.f()?, self.f()?])
    }
    fn vec2(&mut self) -> Result<[f32; 2], String> {
        Ok([self.f()?, self.f()?])
    }
    fn part(&mut self) -> Result<Part, String> {
        let n = self.u()? as usize;
        if n > 65535 {
            return Err("tree vertex limit".into());
        }
        let mut vertices = Vec::with_capacity(n);
        for _ in 0..n {
            vertices.push(Vert {
                pos: self.vec3()?,
                normal: self.vec3()?,
                uv: self.vec2()?,
            })
        }
        let n = self.u()? as usize;
        if n > 3_000_000 || n % 3 != 0 {
            return Err("tree index limit".into());
        }
        let mut indices = Vec::with_capacity(n);
        for _ in 0..n {
            let i = self.u()?;
            if i as usize >= vertices.len() {
                return Err("tree index out of range".into());
            }
            indices.push(i)
        }
        Ok(Part { vertices, indices })
    }
}
fn parse(d: &[u8], source: &[u8], dll_hash: u32) -> Result<(String, Vec<TreeLod>), String> {
    let mut r = Reader { d, p: 0 };
    let magic = r.take(8)?;
    let (animated, native_alpha_refs) = match magic {
        b"PWTREE05" => (false, false),
        b"PWTREE06" | b"PWTREE07" => (true, false),
        b"PWTREE08" => (true, true),
        _ => return Err("unknown tree cache version".into()),
    };
    if r.u()? != dll_hash {
        return Err("tree cache runtime mismatch: rebake".into());
    }
    let mut hash = 2166136261u32;
    for b in source {
        hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
    }
    if r.u()? != hash {
        return Err("tree cache source mismatch: rebake".into());
    }
    let n = r.u()? as usize;
    if n > 4096 {
        return Err("tree texture name too long".into());
    }
    let (name, _, bad) = encoding_rs::GBK.decode(r.take(n)?);
    if bad {
        return Err("invalid tree texture name".into());
    }
    let count = r.u()? as usize;
    if count != 3 {
        return Err("unsupported tree LOD count".into());
    }
    let mut lods = Vec::with_capacity(count);
    for _ in 0..count {
        let branch = r.part()?;
        let frond = r.part()?;
        let (branch_alpha_ref, frond_alpha_ref) = if native_alpha_refs {
            let branch_ref = r.f()?;
            let frond_ref = r.f()?;
            if !(-1.0..=255.0).contains(&branch_ref) || !(-1.0..=255.0).contains(&frond_ref) {
                return Err("invalid native tree alpha reference".into());
            }
            (Some(branch_ref), Some(frond_ref))
        } else {
            (None, None)
        };
        let n = r.u()? as usize;
        if n > 65535 {
            return Err("tree leaf limit".into());
        }
        let mut leaves = Vec::with_capacity(n);
        for _ in 0..n {
            let center = r.vec3()?;
            let rho = r.f()?;
            let mut corners = [[0.; 3]; 4];
            let mut uv = [[0.; 2]; 4];
            for i in 0..4 {
                corners[i] = r.vec3()?;
                uv[i] = r.vec2()?;
            }
            let cluster = if animated { r.u()? } else { 0 };
            leaves.push(Leaf {
                center,
                rho,
                corners,
                uv,
                cluster,
            })
        }
        let (rocking_clusters, rocking) = if animated {
            let clusters = r.u()? as usize;
            let frames = r.u()? as usize;
            if clusters > 512
                || frames != 64
                || leaves.iter().any(|l| l.cluster as usize >= clusters)
            {
                return Err("invalid tree rocking data".into());
            }
            let mut samples = Vec::with_capacity(clusters * 4 * frames);
            for _ in 0..clusters * 4 * frames {
                samples.push(r.vec3()?);
            }
            (clusters, samples)
        } else {
            (0, Vec::new())
        };
        lods.push(TreeLod {
            branch,
            frond,
            branch_alpha_ref,
            frond_alpha_ref,
            leaves,
            rocking,
            rocking_clusters,
        });
    }
    if r.p != d.len() {
        return Err("trailing tree cache bytes".into());
    }
    Ok((name.into_owned(), lods))
}
impl Trees {
    pub fn open(element: &Path, scene: &scene::Scene, cache: &Path) -> Result<Self, String> {
        let placements = scene
            .blocks
            .iter()
            .flat_map(|b| b.trees.iter().cloned())
            .collect();
        let mut types: Vec<Option<TreeMesh>> = (0..scene.tree_types.len()).map(|_| None).collect();
        if !cache.is_dir() {
            eprintln!(
                "SpeedTree cache not found at {}; trees are disabled (see README)",
                cache.display()
            );
            return Ok(Self { types, placements });
        }
        let dll = fs::read(element.join("speedtreert.dll"))
            .map_err(|e| format!("SpeedTreeRT.dll: {e}"))?;
        let mut dll_hash = 2166136261u32;
        for byte in dll {
            dll_hash = (dll_hash ^ u32::from(byte)).wrapping_mul(16777619);
        }
        let mut file = File::open(element.join("trees.pck")).map_err(|e| e.to_string())?;
        let entries: HashMap<_, _> = pck::directory(&mut file)?
            .into_iter()
            .map(|e| (e.name.to_lowercase(), e))
            .collect();
        let mut count = 0;
        for (i, ty) in scene.tree_types.iter().enumerate() {
            let result = (|| -> Result<TreeMesh, String> {
                let data =
                    fs::read(cache.join(format!("tree-{i:03}.pwt"))).map_err(|e| e.to_string())?;
                let src = entries.get(&ty.tree.to_lowercase()).ok_or("missing SPT")?;
                let original = pck::read_entry(&mut file, src)?;
                let (name, lods) = parse(&data, &original, dll_hash)?;
                let name = name.replace('\\', "/");
                let stem = Path::new(&name)
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .ok_or("missing bark name")?;
                let parent = ty.tree.rsplit_once('/').map(|x| x.0).unwrap_or("trees");
                let bark_path = format!("{parent}/{stem}.dds").to_lowercase();
                let fallback = format!("trees/{stem}.dds").to_lowercase();
                let bark_entry = entries
                    .get(&bark_path)
                    .or_else(|| entries.get(&fallback))
                    .ok_or_else(|| format!("missing bark texture {bark_path}"))?;
                let tex_entry = entries
                    .get(&ty.composite.to_lowercase())
                    .ok_or("missing composite")?;
                let bark_bytes = pck::read_entry(&mut file, bark_entry)?;
                let tex_bytes = pck::read_entry(&mut file, tex_entry)?;
                let bark =
                    image::load_from_memory_with_format(&bark_bytes, image::ImageFormat::Dds)
                        .map_err(|e| e.to_string())?
                        .to_rgba8();
                let composite =
                    image::load_from_memory_with_format(&tex_bytes, image::ImageFormat::Dds)
                        .map_err(|e| e.to_string())?
                        .to_rgba8();
                let bark_mips = crate::vegetation_textures::authored_lower_mips(&bark_bytes)
                    .unwrap_or_else(|e| {
                        eprintln!("Tree type {i} bark authored mips unavailable: {e}");
                        Vec::new()
                    });
                let composite_mips = crate::vegetation_textures::authored_lower_mips(&tex_bytes)
                    .unwrap_or_else(|e| {
                        eprintln!("Tree type {i} composite authored mips unavailable: {e}");
                        Vec::new()
                    });
                Ok(TreeMesh {
                    lods,
                    bark,
                    composite,
                    bark_mips,
                    composite_mips,
                })
            })();
            match result {
                Ok(mesh) => {
                    types[i] = Some(mesh);
                    count += 1
                }
                Err(e) => eprintln!("Tree type {i}: {e}"),
            }
        }
        eprintln!(
            "Loaded {count}/{} SpeedTree types from runtime cache",
            types.len()
        );
        Ok(Self { types, placements })
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn accepts_three_empty_lods_and_checks_hashes() {
        let source = b"asset";
        let mut hash = 2166136261u32;
        for b in source {
            hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
        }
        let mut b = b"PWTREE05".to_vec();
        b.extend_from_slice(&42u32.to_le_bytes());
        b.extend_from_slice(&hash.to_le_bytes());
        b.extend_from_slice(&0u32.to_le_bytes());
        b.extend_from_slice(&3u32.to_le_bytes());
        for _ in 0..3 {
            for _ in 0..5 {
                b.extend_from_slice(&0u32.to_le_bytes());
            }
        }
        assert_eq!(parse(&b, source, 42).unwrap().1.len(), 3);
        assert!(parse(&b, source, 43).is_err());
        assert!(parse(&b, b"other", 42).is_err());
        assert!(parse(&b[..b.len() - 1], source, 42).is_err());
    }
    #[test]
    fn reads_native_alpha_references_only_from_pwtree08() {
        let source = b"tree";
        let mut hash = 2166136261u32;
        for b in source {
            hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
        }
        let mut b = b"PWTREE08".to_vec();
        for value in [42u32, hash, 0, 3] {
            b.extend_from_slice(&value.to_le_bytes());
        }
        for _ in 0..3 {
            // Empty branch and frond parts.
            for _ in 0..4 {
                b.extend_from_slice(&0u32.to_le_bytes());
            }
            b.extend_from_slice(&84f32.to_le_bytes());
            b.extend_from_slice(&255f32.to_le_bytes());
            // No leaves, then a valid empty 64-frame rocking table.
            for value in [0u32, 0, 64] {
                b.extend_from_slice(&value.to_le_bytes());
            }
        }
        let lods = parse(&b, source, 42).unwrap().1;
        assert_eq!(lods.len(), 3);
        assert_eq!(lods[0].branch_alpha_ref, Some(84.));
        assert_eq!(lods[0].frond_alpha_ref, Some(255.));
        assert!(parse(&b[..b.len() - 1], source, 42).is_err());
        let mut invalid = b;
        let ref_offset = 8 + 4 * 4 + 4 * 4;
        invalid[ref_offset..ref_offset + 4].copy_from_slice(&256f32.to_le_bytes());
        assert!(parse(&invalid, source, 42).is_err());
    }
    #[test]
    fn accepts_sampled_rocking_and_rejects_invalid_cluster() {
        let source = b"x";
        let hash = (2166136261u32 ^ u32::from(source[0])).wrapping_mul(16777619);
        let mut b = b"PWTREE06".to_vec();
        for value in [42u32, hash, 0, 3] {
            b.extend_from_slice(&value.to_le_bytes());
        }
        for _ in 0..3 {
            for value in [0u32, 0, 0, 0, 1] {
                b.extend_from_slice(&value.to_le_bytes());
            }
            for _ in 0..24 {
                b.extend_from_slice(&0f32.to_le_bytes());
            }
            b.extend_from_slice(&0u32.to_le_bytes());
            b.extend_from_slice(&1u32.to_le_bytes());
            b.extend_from_slice(&64u32.to_le_bytes());
            for frame in 0..4 * 64 {
                for v in [frame as f32, 0., 0.] {
                    b.extend_from_slice(&v.to_le_bytes());
                }
            }
        }
        let parsed = parse(&b, source, 42).unwrap().1;
        assert_eq!(parsed[0].rocking.len(), 256);
        assert_eq!(parsed[0].rocking[4][0], 4.);
        let mut invalid = b.clone();
        let cluster_offset = 8 + 4 * 4 + 5 * 4 + 24 * 4;
        invalid[cluster_offset..cluster_offset + 4].copy_from_slice(&2u32.to_le_bytes());
        assert!(parse(&invalid, source, 42).is_err());
        assert!(parse(&b[..b.len() - 4], source, 42).is_err());
    }
    #[test]
    fn reject_invalid() {
        assert!(parse(b"PWTREE05\0\0\0\0", b"x", 0).is_err());
        assert!(parse(b"garbage", b"", 0).is_err());
    }
}
